+/** Picks `ko` or `en` from an Accept-Language header (q-values, region tags); `fallback` if none match. */
+export function pickLanguage(header, fallback = "en") {
+  let best = null;
+  let bestQ = 0;
+  for (const part of String(header ?? "").split(",")) {
+    const [tag, ...rest] = part.trim().split(";");
+    const lang = tag.trim().toLowerCase().split("-")[0];
+    if (lang !== "ko" && lang !== "en") continue;
+    const qParam = rest.map((r) => r.trim()).find((r) => /^q=/i.test(r));
+    const q = qParam ? Number(qParam.slice(2)) : 1;
+    if (Number.isFinite(q) && q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
